driverScript:
module.exports = {
  sessionId: 0,
  remotePacketId: 0,
  localPacketId: 0,
  connected: false,
  lastReceivedTime: 0,
  config: {},
  handshakeInterval: null,

  onConnect: function(transport, config) {
    this.sessionId = 0;
    this.remotePacketId = 0;
    this.localPacketId = 0;
    this.connected = false;
    this.lastReceivedTime = Date.now();
    this.config = config || {};
    engine.setStatus('connecting', 'Connecting to ATEM...');

    var self = this;
    this.sendSyn(transport);

    if (this.handshakeInterval) clearInterval(this.handshakeInterval);
    this.handshakeInterval = setInterval(function() {
      if (!self.connected) {
        self.sendSyn(transport);
      } else {
        clearInterval(self.handshakeInterval);
        self.handshakeInterval = null;
      }
    }, 1000);
  },

  sendSyn: function(transport) {
    var synPacket = [
      0x10, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
      0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00,
      0x00, 0x00, 0x00, 0x00
    ];
    transport.sendBytes(synPacket);
  },

  onMessage: function(transport, messageText, messageBytes) {
    if (!messageBytes || messageBytes.length < 12) return;
    this.lastReceivedTime = Date.now();

    var flagByte = messageBytes[0];
    var len = ((flagByte & 0x07) << 8) | messageBytes[1];
    var incSessionId = (messageBytes[2] << 8) | messageBytes[3];
    var incRemoteAckId = (messageBytes[4] << 8) | messageBytes[5];
    var incSwitcherPacketId = (messageBytes[10] << 8) | messageBytes[11];

    // ConnectAck from ATEM (bit 4: 0x10)
    if ((flagByte & 0x10) !== 0) {
      this.sessionId = incSessionId;
      this.remotePacketId = 0;
      this.localPacketId = 0;
      this.connected = true;
      this.lastReceivedTime = Date.now();
      if (this.handshakeInterval) {
        clearInterval(this.handshakeInterval);
        this.handshakeInterval = null;
      }
      engine.setStatus('connected', 'Connected to ATEM');
      this.sendAck(transport, 0);
      return;
    }

    if (this.sessionId !== 0 && incSessionId !== this.sessionId) return;

    if (incSwitcherPacketId > this.remotePacketId || (this.remotePacketId > 60000 && incSwitcherPacketId < 1000)) {
      this.remotePacketId = incSwitcherPacketId;
    }

    // Process subcommands
    if (len > 12 && messageBytes.length >= len) {
      var offset = 12;
      while (offset + 8 <= len) {
        var cmdLen = (messageBytes[offset] << 8) | messageBytes[offset + 1];
        if (cmdLen < 8 || offset + cmdLen > len) break;
        var cmdName = String.fromCharCode(
          messageBytes[offset + 4],
          messageBytes[offset + 5],
          messageBytes[offset + 6],
          messageBytes[offset + 7]
        );
        var payload = messageBytes.slice(offset + 8, offset + cmdLen);
        this.handleCommand(cmdName, payload);
        offset += cmdLen;
      }
    }

    // Acknowledge packets from switcher (ACK request bit 0x08 or received packet with ID)
    if ((flagByte & 0x08) !== 0 || incSwitcherPacketId > 0) {
      this.sendAck(transport, this.remotePacketId);
    }
  },

  sendAck: function(transport, ackId) {
    var packet = [
      0x80, 0x0C,
      (this.sessionId >> 8) & 0xFF, this.sessionId & 0xFF,
      (ackId >> 8) & 0xFF, ackId & 0xFF,
      0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    ];
    transport.sendBytes(packet);
  },

  onHeartbeat: function(transport) {
    if (this.connected) {
      var now = Date.now();
      // Watchdog: If no packet received for > 3.5s, reconnect
      if (now - this.lastReceivedTime > 3500) {
        this.connected = false;
        engine.setStatus('connecting', 'Re-syncing with ATEM...');
        this.sendSyn(transport);
        var self = this;
        if (this.handshakeInterval) clearInterval(this.handshakeInterval);
        this.handshakeInterval = setInterval(function() {
          if (!self.connected) {
            self.sendSyn(transport);
          } else {
            clearInterval(self.handshakeInterval);
            self.handshakeInterval = null;
          }
        }, 1000);
      } else if (this.sessionId !== 0) {
        this.sendAck(transport, this.remotePacketId);
      }
    }
  },

  handleCommand: function(name, payload) {
    // 1. Real hardware product name string (e.g. 'ATEM 4 M/E Constellation HD')
    if (name === '_pin' && payload.length > 0) {
      var pinStr = '';
      for (var i = 0; i < payload.length; i++) {
        if (payload[i] === 0) break;
        pinStr += String.fromCharCode(payload[i]);
      }
      pinStr = pinStr.trim();
      if (pinStr.length > 0) {
        engine.setVariable('atem_model', pinStr);
      }
    }
    // 2. Topology Information
    else if (name === '_top' && payload.length >= 2) {
      var meCount = payload[0];
      var sourceCount = payload[1];
      engine.setVariable('atem_me_count', String(meCount));
      engine.setVariable('atem_source_count', String(sourceCount));
    }
    // 3. Protocol Version
    else if (name === '_ver' && payload.length >= 4) {
      var vMajor = (payload[0] << 8) | payload[1];
      var vMinor = (payload[2] << 8) | payload[3];
      engine.setVariable('atem_protocol_version', vMajor + '.' + vMinor);
    }
    // 4. Program Input
    else if ((name === 'PrIn' || name === 'CPgI') && payload.length >= 4) {
      var me = payload[0];
      var input = (payload[2] << 8) | payload[3];
      engine.setVariable('atem_me_' + (me + 1) + '_program_input', String(input));
      if (me === 0) {
        engine.setVariable('atem_program_input', String(input));
      }
    }
    // 5. Preview Input
    else if ((name === 'PrvI' || name === 'CPvI') && payload.length >= 4) {
      var me = payload[0];
      var input = (payload[2] << 8) | payload[3];
      engine.setVariable('atem_me_' + (me + 1) + '_preview_input', String(input));
      if (me === 0) {
        engine.setVariable('atem_preview_input', String(input));
      }
    }
    // 6. Transition State
    else if ((name === 'TrSS' || name === 'TrPr') && payload.length >= 2) {
      var me = payload[0];
      var inTrans = payload[1] !== 0 ? 'true' : 'false';
      engine.setVariable('atem_me_' + (me + 1) + '_in_transition', inTrans);
      if (me === 0) {
        engine.setVariable('atem_in_transition', inTrans);
      }
    }
    // 7. Fade to Black State
    else if ((name === 'FTSA' || name === 'FtbS') && payload.length >= 2) {
      var me = payload[0];
      var ftb = payload[1] !== 0 ? 'true' : 'false';
      engine.setVariable('atem_me_' + (me + 1) + '_ftb_active', ftb);
      if (me === 0) {
        engine.setVariable('atem_ftb_active', ftb);
      }
    }
    // 8. Input Properties & Labels
    else if (name === 'InPr' && payload.length >= 26) {
      var inId = (payload[0] << 8) | payload[1];
      var longName = '';
      for (var j = 2; j < 22; j++) {
        if (payload[j] === 0) break;
        longName += String.fromCharCode(payload[j]);
      }
      longName = longName.trim();
      if (longName.length > 0) {
        engine.setVariable('atem_input_' + inId + '_name', longName);
      }
    }
  },

  onAction: function(transport, actionId, params) {
    params = params || {};
    var rawAct = String(actionId || '').toLowerCase().trim();
    var act = rawAct.replace(/^\/+/, '');
    if (act.indexOf('/') !== -1) {
      act = act.split('/').pop();
    }
    act = act.replace(/^atem_/, '').replace(/^atem\./, '').replace(/^atem-/, '');

    var isAllMe = String(params.me_index || params.me || '').toLowerCase() === 'all';
    var meCount = parseInt(engine.getVariable('atem_me_count') || '1', 10);
    if (isNaN(meCount) || meCount < 1) meCount = 1;

    var defaultMe = (this.config && this.config.me_index) ? this.config.me_index : '1';
    var me = parseInt(params.me_index || params.me || defaultMe, 10) - 1;
    if (isNaN(me) || me < 0) me = 0;

    function getIntParam(keys, defaultVal) {
      for (var i = 0; i < keys.length; i++) {
        var k = keys[i];
        if (params[k] !== undefined && params[k] !== null) {
          var s = String(params[k]).trim();
          if (s !== '') {
            var digits = s.replace(/[^0-9]/g, '');
            if (digits.length > 0) {
              var parsed = parseInt(digits, 10);
              if (!isNaN(parsed)) return parsed;
            }
          }
        }
      }
      return defaultVal;
    }

    var self = this;
    function sendToMe(cmd, payloadBuilder) {
      if (isAllMe) {
        for (var m = 0; m < meCount; m++) {
          self.sendCommand(transport, cmd, payloadBuilder(m));
        }
      } else {
        self.sendCommand(transport, cmd, payloadBuilder(me));
      }
    }

    if (act === 'cut' || act === 'dcut') {
      sendToMe('DCut', function(m) { return [m, 0x00, 0x00, 0x00]; });
      return 'Cut transition executed (M/E ' + (isAllMe ? 'All' : (me + 1)) + ')';
    } else if (act === 'auto' || act === 'auto_fade' || act === 'daut') {
      sendToMe('DAut', function(m) { return [m, 0x00, 0x00, 0x00]; });
      return 'Auto transition executed (M/E ' + (isAllMe ? 'All' : (me + 1)) + ')';
    } else if (act === 'set_program' || act === 'program_input' || act === 'cpgi' || act === 'program' || act === 'pgm') {
      var input = getIntParam(['input_id', 'input', 'value', 'param', 'source'], 1);
      sendToMe('CPgI', function(m) { return [m, 0x00, (input >> 8) & 0xFF, input & 0xFF]; });
      engine.setVariable('atem_program_input', String(input));
      engine.setVariable('atem_me_' + (me + 1) + '_program_input', String(input));
      return 'Program input set to Input ' + input + ' (M/E ' + (isAllMe ? 'All' : (me + 1)) + ')';
    } else if (act === 'set_preview' || act === 'preview_input' || act === 'cpvi' || act === 'preview' || act === 'pvw') {
      var input = getIntParam(['input_id', 'input', 'value', 'param', 'source'], 2);
      sendToMe('CPvI', function(m) { return [m, 0x00, (input >> 8) & 0xFF, input & 0xFF]; });
      engine.setVariable('atem_preview_input', String(input));
      engine.setVariable('atem_me_' + (me + 1) + '_preview_input', String(input));
      return 'Preview input set to Input ' + input + ' (M/E ' + (isAllMe ? 'All' : (me + 1)) + ')';
    } else if (act === 'ftb' || act === 'fade_to_black' || act === 'ftsa' || act === 'ftba') {
      sendToMe('FtbA', function(m) { return [m, 0x02, 0x58, 0x99]; });
      sendToMe('FTSA', function(m) { return [m, 0x00, 0x00, 0x00]; });
      return 'Fade to Black toggled (M/E ' + (isAllMe ? 'All' : (me + 1)) + ')';
    } else if (act === 'run_macro' || act === 'macro' || act === 'mrun') {
      var macroIdx = Math.max(0, getIntParam(['macro_index', 'macro_id', 'macro', 'value', 'param'], 1) - 1);
      this.sendCommand(transport, 'MRUN', [(macroIdx >> 8) & 0xFF, macroIdx & 0xFF, 0x00, 0x00]);
      return 'Macro ' + (macroIdx + 1) + ' triggered';
    }

    return 'Executed action ' + actionId;
  },

  sendCommand: function(transport, name, payload) {
    this.localPacketId = (this.localPacketId + 1) & 0x7FFF;
    var packetId = this.localPacketId;
    var cmdLen = 8 + payload.length;
    var totalLen = 12 + cmdLen;
    var flags = 0x08;
    var packet = [
      flags | ((totalLen >> 8) & 0x07), totalLen & 0xFF,
      (this.sessionId >> 8) & 0xFF, this.sessionId & 0xFF,
      (this.remotePacketId >> 8) & 0xFF, this.remotePacketId & 0xFF,
      0x00, 0x00,
      0x00, 0x00,
      (packetId >> 8) & 0xFF, packetId & 0xFF,
      (cmdLen >> 8) & 0xFF, cmdLen & 0xFF, 0x00, 0x00,
      name.charCodeAt(0) & 0xFF, name.charCodeAt(1) & 0xFF, name.charCodeAt(2) & 0xFF, name.charCodeAt(3) & 0xFF
    ];
    for (var i = 0; i < payload.length; i++) {
      packet.push(payload[i] & 0xFF);
    }
    transport.sendBytes(packet);
  }
};
